option.value:
/* Reset & Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --primary-color: #6366f1;
    --secondary-color: #8b5cf6;
    --accent-color: #ec4899;
    --dark-bg: #0f172a;
    --dark-secondary: #1e293b;
    --dark-tertiary: #334155;
    --text-primary: #f1f5f9;
    --text-secondary: #cbd5e1;
    --text-muted: #94a3b8;
    --gradient-1: linear-gradient(135deg, #6366f1 0%, #8b5cf6 50%, #ec4899 100%);
    --gradient-2: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
    --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.1);
    --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.2);
    --shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.3);
    --shadow-glow: 0 0 20px rgba(99, 102, 241, 0.3);
}

html {
    scroll-behavior: smooth;
}

body {
    background-color: var(--dark-bg);
    color: var(--text-primary);
    line-height: 1.6;
    overflow-x: hidden;
    font-family: "Inter", "Segoe UI", Roboto, Arial, sans-serif;
}

html,
body {
    cursor: auto;
}

a,
button,
[role="button"],
.project-card,
.project-card-action-link,
.project-detail-link,
.project-gallery-item,
.carousel-arrow,
.dot,
.accordion-header,
.social-link,
.btn,
input[type="submit"],
input[type="button"] {
    cursor: pointer;
}

@media (hover: none), (pointer: coarse) {
    html,
    body,
    a,
    button,
    [role="button"],
    .project-card,
    .project-card-action-link,
    .project-detail-link,
    .project-gallery-item,
    .carousel-arrow,
    .dot,
    .accordion-header,
    .social-link,
    .btn,
    input[type="submit"],
    input[type="button"] {
        cursor: auto !important;
    }
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

/* Navigation Bar */
.navbar {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    background: rgba(15, 23, 42, 0.9);
    backdrop-filter: blur(10px);
    padding: 1rem 0;
    box-shadow: var(--shadow-md);
    transition: all 0.3s ease;
    z-index: 1000;
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    font-size: 1.2rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    color: var(--text-primary);
    white-space: nowrap;
}

.navbar.scrolled {
    padding: 0.5rem 0;
    background: rgba(15, 23, 42, 0.95);
}


.nav-menu {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-link {
    color: var(--text-secondary);
    text-decoration: none;
    font-weight: 500;
    transition: all 0.3s ease;
    position: relative;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -5px;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--gradient-1);
    transition: width 0.3s ease;
}

.nav-link:hover {
    color: var(--text-primary);
}

.nav-link:hover::after {
    width: 100%;
}

.nav-link.active {
    color: var(--primary-color);
}

.hamburger {
    display: none;
    flex-direction: column;
    cursor: pointer;
    gap: 4px;
}

.hamburger span {
    width: 25px;
    height: 3px;
    background: var(--text-primary);
    border-radius: 3px;
    transition: all 0.3s ease;
}

/* Hero Section */
.hero {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 120px 20px 80px;
    max-width: 1200px;
    margin: 0 auto;
    gap: 60px;
}

.hero-content {
    flex: 1;
    max-width: 600px;
}

.hero-title {
    font-size: 3.5rem;
    font-weight: 800;
    margin-bottom: 1rem;
    line-height: 1.2;
}

.gradient-text {
    background: var(--gradient-1);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.hero-subtitle {
    font-size: 1.5rem;
    color: var(--text-secondary);
    margin-bottom: 1rem;
}

.hero-description {
    font-size: 1.1rem;
    color: var(--text-muted);
    margin-bottom: 2rem;
}

.hero-buttons {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.btn {
    padding: 12px 30px;
    border-radius: 8px;
    text-decoration: none;
    font-weight: 600;
    transition: all 0.3s ease;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    display: inline-block;
}

.btn-primary {
    background: var(--gradient-1);
    color: white;
    box-shadow: var(--shadow-glow);
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 0 30px rgba(99, 102, 241, 0.5);
}

.btn-secondary {
    background: transparent;
    color: var(--text-primary);
    border: 2px solid var(--primary-color);
}

.btn-secondary:hover {
    background: var(--primary-color);
    transform: translateY(-2px);
}

.btn-full {
    width: 100%;
    text-align: center;
}

.hero-image {
    flex: 1;
    display: flex;
    justify-content: center;
    align-items: center;
}

.image-placeholder {
    width: 400px;
    height: 400px;
    /*background: var(--gradient-2);*/
    /*border-radius: 50%;*/
    position: relative;
    /*box-shadow: var(--shadow-glow);*/
    animation: float 100s ease-in-out infinite;
}

@keyframes float {
    0%, 100% { transform: translateY(0px); }
    50% { transform: translateY(-20px); }
}

.floating-icon {
    position: absolute;
    font-size: 3rem;
    animation: rotate 20s linear infinite;
}

.icon-1 {
    top: 10%;
    left: 10%;
    animation: float 3s ease-in-out infinite;
}

.icon-2 {
    top: 10%;
    right: 10%;
    animation: float 4s ease-in-out infinite;
}

.icon-3 {
    bottom: 10%;
    left: 10%;
    animation: float 5s ease-in-out infinite;
}

.icon-4 {
    bottom: 10%;
    right: 10%;
    animation: float 3.5s ease-in-out infinite;
}

/* Animations */
.animate-fade-in {
    animation: fadeIn 1s ease-out;
}

.animate-fade-in-delay {
    animation: fadeIn 1s ease-out 0.2s backwards;
}

.animate-fade-in-delay-2 {
    animation: fadeIn 1s ease-out 0.4s backwards;
}

.animate-fade-in-delay-3 {
    animation: fadeIn 1s ease-out 0.6s backwards;
}

.animate-slide-in {
    animation: slideIn 1s ease-out 0.3s backwards;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateX(50px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

/* Section Styles */
section {
    padding: 100px 20px;
}

.section-title {
    font-size: 2.5rem;
    text-align: center;
    margin-bottom: 4rem;
    position: relative;
}

.section-title::after {
    content: '';
    position: absolute;
    bottom: -10px;
    left: 50%;
    transform: translateX(-50%);
    width: 100px;
    height: 4px;
    background: var(--gradient-1);
    border-radius: 2px;
}

/* About Section */
.about {
    background: var(--dark-secondary);
}

/* Experience Section */
.experience {
    background: var(--dark-bg);
}

.experience-grid {
    display: grid;
    grid-template-columns: repeat(12, minmax(0, 1fr));
    gap: 1.25rem;
}

.experience-card {
    background: linear-gradient(160deg, rgba(30, 41, 59, 0.95), rgba(15, 23, 42, 0.95));
    border: 1px solid var(--dark-tertiary);
    border-radius: 16px;
    padding: 1.2rem;
    transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
}

.experience-card:hover {
    transform: translateY(-4px);
    border-color: rgba(139, 92, 246, 0.7);
    box-shadow: 0 10px 28px rgba(99, 102, 241, 0.2);
}

.experience-card--timeline {
    grid-column: span 6;
    display: grid;
    grid-template-columns: auto 1fr;
    column-gap: 0.9rem;
    row-gap: 0.45rem;
}

.experience-card--timeline .experience-icon {
    grid-row: 1 / span 4;
}

.experience-card--featured {
    grid-column: span 6;
    position: relative;
    overflow: hidden;
}

.experience-card--featured::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    padding: 1px;
    background: linear-gradient(120deg, rgba(99, 102, 241, 0.85), rgba(139, 92, 246, 0.8), rgba(236, 72, 153, 0.7));
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    opacity: 0.9;
    pointer-events: none;
}

.experience-top-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    margin-bottom: 0.7rem;
}

.experience-card--compact {
    grid-column: span 12;
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.9rem;
    align-items: start;
}

.experience-compact-body {
    display: grid;
    gap: 0.34rem;
}

.experience-icon {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: var(--gradient-1);
    font-size: 1.2rem;
    box-shadow: 0 8px 18px rgba(99, 102, 241, 0.3);
}

.experience-meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.7rem;
    flex-wrap: wrap;
}

.experience-company {
    color: var(--text-primary);
    font-size: 1.08rem;
    font-weight: 700;
}

.experience-role {
    color: #c4b5fd;
    font-weight: 600;
    margin: 0;
}

.experience-project {
    color: #93c5fd;
    margin: 0;
    font-size: 0.95rem;
}

.experience-date {
    color: var(--text-muted);
    font-size: 0.86rem;
}

.experience-description {
    color: var(--text-secondary);
    margin: 0;
}

.experience-description a {
    color: #93c5fd; /* Light blue for links */
    text-decoration: underline;
    transition: color 0.3s ease;
}

.experience-description a:hover {
    color: #c4b5fd; /* Lighter purple on hover */
}

.about-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: center;
}

.profile-card {
    position: relative;
    width: 300px;
    height: 300px;
    margin: 0 auto;
}

.profile-image {
    width: 100%;
    height: 100%;
    background: var(--gradient-2);
    border-radius: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 8rem;
    box-shadow: var(--shadow-lg);
    position: relative;
    z-index: 2;
}

.card-glow {
    position: absolute;
    top: 20px;
    left: 20px;
    right: -20px;
    bottom: -20px;
    background: var(--gradient-1);
    border-radius: 20px;
    filter: blur(20px);
    opacity: 0.3;
    z-index: 1;
}

.about-text h3 {
    font-size: 2rem;
    margin-bottom: 1.5rem;
    color: var(--text-primary);
}

.about-text p {
    color: var(--text-secondary);
    margin-bottom: 1rem;
    font-size: 1.1rem;
}

.about-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
    margin-top: 3rem;
}
/*.skills{*/
/*    background: var(--dar);*/
/*}*/

.stat-item {
    text-align: center;
    padding: 1.5rem;
    background: var(--dark-tertiary);
    border-radius: 12px;
    transition: transform 0.3s ease;
}

.stat-item:hover {
    transform: translateY(-5px);
}

.stat-item h4 {
    font-size: 2.5rem;
    background: var(--gradient-1);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 0.5rem;
}

.stat-item p {
    color: var(--text-muted);
    font-size: 0.9rem;
}

/* Skills Section */
.skills-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.skill-card {
    background: var(--dark-secondary);
    padding: 2rem;
    border-radius: 16px;
    text-align: center;
    transition: all 0.3s ease;
    border: 1px solid transparent;
}

.skill-card:hover {
    transform: translateY(-10px);
    border-color: var(--primary-color);
    box-shadow: var(--shadow-glow);
}

.skill-icon {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.skill-card h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
    color: var(--text-primary);
}

.skill-card p {
    color: var(--text-muted);
    margin-bottom: 1.5rem;
}

.skill-bar {
    width: 100%;
    height: 8px;
    background: var(--dark-tertiary);
    border-radius: 4px;
    overflow: hidden;
}

.skill-progress {
    height: 100%;
    background: var(--gradient-1);
    border-radius: 4px;
    width: 0;
    transition: width 1s ease-out;
}

/* Projects Section */
.projects {
    background: var(--dark-secondary);
}

.projects-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 2rem;
    overflow: visible;
}

.project-card {
    background: var(--dark-bg);
    border-radius: 16px;
    overflow: hidden;
    border: 1px solid var(--dark-tertiary);
    position: relative;
    isolation: isolate;
    transform: translateZ(0) scale(1);
    transform-origin: center center;
    will-change: transform;
    transition: transform 0.24s ease, box-shadow 0.24s ease;
}

.project-card::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    padding: 2px;
    background: linear-gradient(120deg, #6366f1, #8b5cf6, #ec4899, #6366f1);
    background-size: 240% 240%;
    opacity: 0;
    z-index: 3;
    pointer-events: none;
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask-composite: exclude;
    transition: opacity 0.25s ease;
}

.project-card > * {
    position: relative;
    z-index: 1;
}

.project-card:hover {
    transform: translateZ(0) scale(1.05);
    z-index: 30;
    box-shadow: 0 10px 26px rgba(99, 102, 241, 0.22);
}

.project-card:hover::before {
    opacity: 1;
    animation: projectOutlineFlow 0.95s linear infinite;
}

@keyframes projectOutlineFlow {
    0% {
        background-position: 0% 50%;
    }
    100% {
        background-position: 200% 50%;
    }
}

.project-image {
    position: relative;
    height: 250px;
    background: var(--dark-tertiary);
    overflow: hidden;
}

.project-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 6rem;
    background: var(--gradient-2);
}

.project-image {
    position: relative;
    width: 100%;
    height: 220px;
    overflow: hidden;
    border-radius: 12px;
}

.project-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    position: relative;
    z-index: 0;
}

.project-card[data-project-id="nuts-and-bolts"] .project-image img {
    object-position: center 25%;
}

.project-card[data-project-id="city-jam"] .project-image img {
    object-position: center 60%;
}

.project-card[data-project-id="army-runner"] .project-image img {
    object-position: center 40%;
}

/* Ball Blast cover alignment: ikinci degeri degistirerek yukari/asagi ayarlayabilirsin. */
.project-card[data-project-id="ball-blast-clone"] .project-image img {
    object-position: center 20%;
}

.project-card-links {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    justify-content: flex-end;
    gap: 0.6rem;
    padding: 0.7rem 0.8rem;
    background: linear-gradient(to top, rgba(15, 23, 42, 0.98), rgba(15, 23, 42, 0.35), rgba(15, 23, 42, 0));
    z-index: 2;
}

.project-card-action-link {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.95), rgba(236, 72, 153, 0.95));
    border: 1px solid rgba(248, 250, 252, 0.28);
    color: #fff;
    box-shadow: 0 6px 16px rgba(99, 102, 241, 0.35);
    transition: all 0.22s ease;
}

.project-card-action-link:hover {
    color: #fff;
    border-color: rgba(248, 250, 252, 0.55);
    transform: translateY(-2px) scale(1.04);
    box-shadow: 0 10px 22px rgba(236, 72, 153, 0.35);
}

.project-card-action-link:focus-visible {
    outline: 2px solid #f8fafc;
    outline-offset: 2px;
}

.project-card-action-link svg {
    width: 18px;
    height: 18px;
}

.project-overlay {
    position: absolute;
    inset: 0; /* top:0, right:0, bottom:0, left:0 */
    width: 100%;
    height: 100%;
}

.project-overlay img {
    position: absolute;
    width: 100%;
    height: 100%;
    object-fit: cover; /* genişliği ve yüksekliği tam doldurur */
    object-position: center;
}

.project-links {
    position: absolute;
    bottom: 10px;
    left: 10px;
    z-index: 1;
    display: flex;
    gap: 8px;
}

.project-placeholder {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    opacity: 0.2;
}


.project-links {
    display: flex;
    gap: 1rem;
}

.project-link {
    padding: 10px 20px;
    background: white;
    color: var(--primary-color);
    text-decoration: none;
    border-radius: 8px;
    font-weight: 600;
    transition: all 0.3s ease;
}

.project-link:hover {
    transform: scale(1.1);
}

.project-content {
    padding: 1.5rem;
}

.project-content h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
    color: var(--text-primary);
}

.project-content p {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    font-size: 0.95rem;
}

.project-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.tag {
    padding: 6px 12px;
    background: var(--dark-tertiary);
    color: var(--primary-color);
    border-radius: 20px;
    font-size: 0.85rem;
    font-weight: 500;
}

/* Testimonials / Carousel Section */
.testimonials {
    background: var(--dark-bg);
    overflow: hidden;
    position: relative;
}

.section-subtitle {
    text-align: center;
    color: var(--text-muted);
    font-size: 1.1rem;
    margin-top: -2rem;
    margin-bottom: 4rem;
}

.carousel-3d-container {
    position: relative;
    width: 100%;
    height: 600px;
    perspective: 2000px;
    margin-top: 3rem;
}

.carousel-3d {
    position: relative;
    width: 100%;
    height: 100%;
    transform-style: preserve-3d;
    transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-item {
    position: absolute;
    width: 500px;
    height: 450px;
    left: 50%;
    top: 50%;
    transform-style: preserve-3d;
    transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
    cursor: pointer;
}

.carousel-card {
    width: 100%;
    height: 100%;
    background: var(--dark-secondary);
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    border: 1px solid var(--dark-tertiary);
    transition: all 0.3s ease;
    transform-style: preserve-3d;
    backface-visibility: hidden;
}

.carousel-item.active .carousel-card {
    border-color: var(--primary-color);
    box-shadow: 0 20px 60px rgba(99, 102, 241, 0.4);
}

.carousel-item:not(.active) .carousel-card {
    opacity: 0.6;
    filter: blur(1px);
}

.carousel-item:hover:not(.active) .carousel-card {
    opacity: 0.8;
    transform: scale(1.02);
}

.card-image {
    position: relative;
    height: 200px;
    background: var(--gradient-2);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.card-image::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.2) 0%, rgba(139, 92, 246, 0.2) 100%);
}

.image-icon {
    font-size: 5rem;
    position: relative;
    z-index: 2;
    animation: float 3s ease-in-out infinite;
}

.card-badge {
    position: absolute;
    top: 20px;
    right: 20px;
    background: rgba(255, 255, 255, 0.2);
    backdrop-filter: blur(10px);
    padding: 8px 16px;
    border-radius: 20px;
    font-size: 1.2rem;
    z-index: 3;
}

.card-content {
    padding: 2rem;
    position: relative;
}

.quote-icon {
    font-size: 4rem;
    color: var(--primary-color);
    opacity: 0.3;
    position: absolute;
    top: 0;
    left: 1rem;
    line-height: 1;
}

.testimonial-text {
    color: var(--text-secondary);
    font-size: 1rem;
    line-height: 1.7;
    margin-bottom: 1.5rem;
    position: relative;
    z-index: 2;
    margin-top: 1rem;
}

.testimonial-author {
    border-top: 1px solid var(--dark-tertiary);
    padding-top: 1rem;
}

.testimonial-author h4 {
    color: var(--text-primary);
    font-size: 1.2rem;
    margin-bottom: 0.25rem;
}

.testimonial-author p {
    color: var(--text-muted);
    font-size: 0.9rem;
}

/* Carousel Navigation Dots */
.carousel-dots {
    position: absolute;
    bottom: 30px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    gap: 12px;
    z-index: 10;
}

.dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: var(--dark-tertiary);
    cursor: pointer;
    transition: all 0.3s ease;
    border: 2px solid transparent;
}

.dot:hover {
    background: var(--text-muted);
    transform: scale(1.2);
}

.dot.active {
    background: var(--gradient-1);
    border-color: var(--primary-color);
    transform: scale(1.3);
    box-shadow: 0 0 10px rgba(99, 102, 241, 0.5);
}

/* Carousel Arrow Buttons */
.carousel-arrow {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: var(--dark-secondary);
    border: 2px solid var(--dark-tertiary);
    color: var(--text-primary);
    cursor: pointer;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
    backdrop-filter: blur(10px);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

.carousel-arrow:hover {
    background: var(--gradient-1);
    border-color: var(--primary-color);
    transform: translateY(-50%) scale(1.1);
    box-shadow: 0 8px 24px rgba(99, 102, 241, 0.4);
}

.carousel-arrow:active {
    transform: translateY(-50%) scale(0.95);
}

.carousel-arrow svg {
    width: 30px;
    height: 30px;
    stroke-width: 3;
}

.carousel-arrow-prev {
    left: 50px;
}

.carousel-arrow-next {
    right: 50px;
}

/* Arrow animation on hover */
.carousel-arrow-prev:hover svg {
    animation: arrowBounceLeft 0.6s ease-in-out infinite;
}

.carousel-arrow-next:hover svg {
    animation: arrowBounceRight 0.6s ease-in-out infinite;
}

@keyframes arrowBounceLeft {
    0%, 100% { transform: translateX(0); }
    50% { transform: translateX(-5px); }
}

@keyframes arrowBounceRight {
    0%, 100% { transform: translateX(0); }
    50% { transform: translateX(5px); }
}

/* Carousel Hint */
.carousel-hint {
    position: absolute;
    bottom: 80px;
    left: 50%;
    transform: translateX(-50%);
    text-align: center;
    opacity: 0.6;
    animation: pulse 2s ease-in-out infinite;
}

.hint-icon {
    font-size: 2rem;
    display: block;
    margin-bottom: 0.5rem;
}

.carousel-hint p {
    color: var(--text-muted);
    font-size: 0.9rem;
}

@keyframes pulse {
    0%, 100% { opacity: 0.4; transform: translateX(-50%) translateY(0); }
    50% { opacity: 0.8; transform: translateX(-50%) translateY(-5px); }
}

/* 3D Carousel Positioning */
.carousel-item[data-position="0"] {
    transform: translate(-50%, -50%) translateZ(0) scale(1);
    z-index: 5;
    opacity: 1;
}

.carousel-item[data-position="1"] {
    transform: translate(-30%, -50%) translateZ(-300px) translateX(400px) scale(0.8);
    z-index: 3;
    opacity: 0.7;
}

.carousel-item[data-position="-1"] {
    transform: translate(-70%, -50%) translateZ(-300px) translateX(-400px) scale(0.8);
    z-index: 3;
    opacity: 0.7;
}

.carousel-item[data-position="2"] {
    transform: translate(-20%, -50%) translateZ(-500px) translateX(600px) scale(0.6);
    z-index: 1;
    opacity: 0.4;
}

.carousel-item[data-position="-2"] {
    transform: translate(-80%, -50%) translateZ(-500px) translateX(-600px) scale(0.6);
    z-index: 1;
    opacity: 0.4;
}

/* Modal Overlay & Wrapper */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.85);
    backdrop-filter: blur(10px);
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.modal-overlay.active {
    opacity: 1;
    visibility: visible;
}

.modal-wrapper {
    position: relative;
    width: 90%;
    max-width: 800px;
    max-height: 90vh;
    background: var(--dark-secondary);
    border-radius: 24px;
    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.5);
    border: 1px solid var(--dark-tertiary);
    transform: scale(0.9) translateY(30px);
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
}

.modal-overlay.active .modal-wrapper {
    transform: scale(1) translateY(0);
}

/* Modal Close Button */
.modal-close {
    position: absolute;
    top: 20px;
    right: 20px;
    width: 45px;
    height: 45px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.1);
    border: 2px solid var(--dark-tertiary);
    color: var(--text-primary);
    cursor: pointer;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
    backdrop-filter: blur(10px);
}

.modal-close:hover {
    background: var(--gradient-1);
    border-color: var(--primary-color);
    transform: rotate(90deg) scale(1.1);
    box-shadow: 0 4px 16px rgba(99, 102, 241, 0.4);
}

.modal-close svg {
    width: 24px;
    height: 24px;
}

/* Modal Content */
.modal-content {
    max-height: 90vh;
    overflow-y: auto;
    padding: 0;
}

/* Custom Scrollbar for Modal */
.modal-content::-webkit-scrollbar {
    width: 8px;
}

.modal-content::-webkit-scrollbar-track {
    background: var(--dark-tertiary);
    border-radius: 4px;
}

.modal-content::-webkit-scrollbar-thumb {
    background: var(--primary-color);
    border-radius: 4px;
}

.modal-content::-webkit-scrollbar-thumb:hover {
    background: var(--secondary-color);
}

/* Modal Header */
.modal-header {
    background: var(--gradient-2);
    padding: 3rem 3rem 2rem;
    display: flex;
    align-items: center;
    gap: 2rem;
    position: relative;
}

.modal-header::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.2) 0%, rgba(139, 92, 246, 0.2) 100%);
}

.modal-avatar {
    position: relative;
    width: 120px;
    height: 120px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.2);
    backdrop-filter: blur(10px);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 4rem;
    border: 3px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
    z-index: 2;
    animation: modalAvatarPulse 2s ease-in-out infinite;
}

@keyframes modalAvatarPulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.05); }
}

.modal-header-info {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    position: relative;
    z-index: 2;
}

.modal-header-info h2 {
    font-size: 2.5rem;
    margin: 0;
    color: var(--text-primary);
}

.modal-header-info p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin: 0;
}

.modal-rating {
    font-size: 1.5rem;
    letter-spacing: 4px;
    margin: 0;
}

/* Modal Body */
.modal-body {
    padding: 3rem;
    position: relative;
}

.quote-mark {
    font-size: 6rem;
    color: var(--primary-color);
    opacity: 0.2;
    line-height: 1;
    position: absolute;
    top: 2rem;
    left: 2rem;
}

.quote-mark-end {
    top: auto;
    bottom: 2rem;
    left: auto;
    right: 2rem;
    transform: rotate(180deg);
}

.modal-testimonial {
    font-size: 1.3rem;
    line-height: 1.8;
    color: var(--text-secondary);
    text-align: center;
    position: relative;
    z-index: 2;
    padding: 0 2rem;
}

/* Modal Footer */
.modal-footer {
    padding: 2rem 3rem 3rem;
    background: var(--dark-bg);
    border-top: 1px solid var(--dark-tertiary);
}

.modal-info-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.modal-info-item {
    display: flex;
    align-items: flex-start;
    gap: 1rem;
    padding: 1.5rem;
    background: var(--dark-secondary);
    border-radius: 12px;
    border: 1px solid var(--dark-tertiary);
    transition: all 0.3s ease;
}

.modal-info-item:hover {
    transform: translateY(-5px);
    border-color: var(--primary-color);
    box-shadow: 0 8px 16px rgba(99, 102, 241, 0.2);
}

.info-icon {
    font-size: 2rem;
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--gradient-1);
    border-radius: 12px;
    flex-shrink: 0;
}

.info-content h4 {
    font-size: 0.9rem;
    color: var(--text-muted);
    margin-bottom: 0.25rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.info-content p {
    font-size: 1.1rem;
    color: var(--text-primary);
    font-weight: 600;
}

/* Modal Technologies */
.modal-technologies {
    margin-top: 2rem;
}

.modal-technologies h4 {
    font-size: 1.1rem;
    color: var(--text-primary);
    margin-bottom: 1rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.tech-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
}

.tech-tag {
    padding: 10px 20px;
    background: var(--gradient-2);
    color: var(--primary-color);
    border-radius: 20px;
    font-size: 0.95rem;
    font-weight: 600;
    border: 1px solid var(--primary-color);
    box-shadow: 0 4px 12px rgba(99, 102, 241, 0.2);
    transition: all 0.3s ease;
    cursor: default;
}

.tech-tag:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 20px rgba(99, 102, 241, 0.4);
}

/* Modal Accordion */
.modal-accordion {
    margin-top: 2.5rem;
}

.modal-accordion h4 {
    font-size: 1.1rem;
    color: var(--text-primary);
    margin-bottom: 1rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.accordion-container {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.accordion-item {
    background: var(--dark-secondary);
    border: 1px solid var(--dark-tertiary);
    border-radius: 12px;
    overflow: hidden;
    transition: all 0.3s ease;
}

.accordion-item.active {
    border-color: var(--primary-color);
    box-shadow: 0 4px 16px rgba(99, 102, 241, 0.2);
}

.accordion-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1.25rem 1.5rem;
    cursor: pointer;
    user-select: none;
    transition: all 0.3s ease;
    background: transparent;
}

.accordion-header:hover {
    background: rgba(99, 102, 241, 0.1);
}

.accordion-item.active .accordion-header {
    background: rgba(99, 102, 241, 0.15);
}

.accordion-title {
    display: flex;
    align-items: center;
    gap: 1rem;
    flex: 1;
}

.accordion-icon {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--gradient-1);
    border-radius: 10px;
    font-size: 1.3rem;
    flex-shrink: 0;
}

.accordion-title h5 {
    font-size: 1.1rem;
    color: var(--text-primary);
    margin: 0;
}

.accordion-arrow {
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-secondary);
    transition: transform 0.3s ease;
}

.accordion-item.active .accordion-arrow {
    transform: rotate(180deg);
    color: var(--primary-color);
}

.accordion-arrow svg {
    width: 20px;
    height: 20px;
}

.accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-item.active .accordion-content {
    max-height: 1000px;
}

.accordion-body {
    padding: 0 1.5rem 1.5rem;
    color: var(--text-secondary);
    line-height: 1.7;
}

.accordion-body p {
    margin-bottom: 1rem;
}

.accordion-body ul {
    list-style: none;
    padding: 0;
    margin: 1rem 0;
}

.accordion-body ul li {
    padding: 0.5rem 0;
    padding-left: 1.5rem;
    position: relative;
}

.accordion-body ul li::before {
    content: '▹';
    position: absolute;
    left: 0;
    color: var(--primary-color);
    font-size: 1.2rem;
}

.accordion-body ul li strong {
    color: var(--text-primary);
}

.accordion-highlight {
    background: rgba(99, 102, 241, 0.1);
    border-left: 3px solid var(--primary-color);
    padding: 1rem 1.5rem;
    margin: 1rem 0;
    border-radius: 8px;
}

.accordion-highlight p {
    margin: 0;
    color: var(--text-primary);
    font-weight: 500;
}

/* Modal Responsive */
@media (max-width: 768px) {
    .modal-wrapper {
        width: 95%;
        max-height: 95vh;
        border-radius: 16px;
    }

    .modal-header {
        flex-direction: column;
        text-align: center;
        padding: 2rem 1.5rem 1.5rem;
    }

    .modal-avatar {
        width: 100px;
        height: 100px;
        font-size: 3rem;
    }

    .modal-header-info h2 {
        font-size: 1.8rem;
    }

    .modal-body {
        padding: 2rem 1.5rem;
    }

    .modal-testimonial {
        font-size: 1.1rem;
        padding: 0 1rem;
    }

    .modal-footer {
        padding: 1.5rem;
    }

    .modal-info-grid {
        grid-template-columns: 1fr;
        gap: 1rem;
    }

    .modal-close {
        width: 40px;
        height: 40px;
        top: 15px;
        right: 15px;
    }

    .modal-close svg {
        width: 20px;
        height: 20px;
    }

    .quote-mark {
        font-size: 4rem;
        top: 1rem;
        left: 1rem;
    }

    .quote-mark-end {
        bottom: 1rem;
        right: 1rem;
    }
}


/* Contact Section */
.contact-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
}

.contact-info h3 {
    font-size: 2rem;
    margin-bottom: 1rem;
}

.contact-info > p {
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.contact-details {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.contact-item {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 1rem;
    background: var(--dark-secondary);
    border-radius: 12px;
    transition: transform 0.3s ease;
}

.contact-item:hover {
    transform: translateX(10px);
}

.contact-icon {
    font-size: 2rem;
    width: 60px;
    height: 60px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--gradient-1);
    border-radius: 12px;
}

.contact-item h4 {
    color: var(--text-primary);
    margin-bottom: 0.25rem;
}

.contact-item p {
    color: var(--text-muted);
    font-size: 0.9rem;
}

.social-links {
    display: flex;
    gap: 1rem;
}

.social-link {
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--dark-secondary);
    border-radius: 12px;
    color: var(--text-primary);
    transition: all 0.3s ease;
}

.social-link:hover {
    background: var(--gradient-1);
    transform: translateY(-5px);
}

.social-link svg {
    width: 24px;
    height: 24px;
}

.contact-form {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.form-group {
    display: flex;
    flex-direction: column;
}

.form-group input,
.form-group textarea {
    padding: 1rem;
    background: var(--dark-secondary);
    border: 2px solid var(--dark-tertiary);
    border-radius: 8px;
    color: var(--text-primary);
    font-size: 1rem;
    font-family: inherit;
    transition: all 0.3s ease;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: var(--shadow-glow);
}

.form-group textarea {
    resize: vertical;
    min-height: 120px;
}

/* Footer */
.footer {
    background: var(--dark-secondary);
    padding: 2rem;
    text-align: center;
    color: var(--text-muted);
}

.footer p {
    margin: 0.5rem 0;
}

/* Responsive Design */
@media (max-width: 968px) {
    .hero {
        flex-direction: column;
        text-align: center;
        padding-top: 100px;
    }

    .hero-content {
        max-width: 100%;
    }

    .hero-title {
        font-size: 2.5rem;
    }

    .hero-buttons {
        justify-content: center;
    }

    .image-placeholder {
        width: 300px;
        height: 300px;
    }

    .about-content {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .about-stats {
        grid-template-columns: repeat(3, 1fr);
    }

    .contact-content {
        grid-template-columns: 1fr;
    }

    .experience-card--timeline,
    .experience-card--featured,
    .experience-card--compact {
        grid-column: span 12;
    }

    .nav-menu {
        position: fixed;
        left: -100%;
        top: 70px;
        flex-direction: column;
        background: rgba(15, 23, 42, 0.98);
        width: 100%;
        text-align: center;
        transition: left 0.3s;
        box-shadow: var(--shadow-lg);
        padding: 2rem 0;
    }

    .nav-menu.active {
        left: 0;
    }

    .hamburger {
        display: flex;
    }

    .hamburger.active span:nth-child(1) {
        transform: rotate(45deg) translate(8px, 8px);
    }

    .hamburger.active span:nth-child(2) {
        opacity: 0;
    }

    .hamburger.active span:nth-child(3) {
        transform: rotate(-45deg) translate(8px, -8px);
    }
}

@media (max-width: 768px) {
    .hero-title {
        font-size: 2rem;
    }

    .hero-subtitle {
        font-size: 1.2rem;
    }

    .section-title {
        font-size: 2rem;
    }

    .about-stats {
        grid-template-columns: 1fr;
    }

    .skills-grid {
        grid-template-columns: 1fr;
    }

    .projects-grid {
        grid-template-columns: 1fr;
    }

    section {
        padding: 60px 20px;
    }

    /* Carousel mobile responsive */
    .carousel-3d-container {
        height: 500px;
        perspective: 1000px;
    }

    .carousel-item {
        width: 90%;
        max-width: 350px;
        height: 400px;
    }

    .carousel-item[data-position="1"],
    .carousel-item[data-position="-1"] {
        transform: translate(-50%, -50%) translateZ(-200px) scale(0.7);
    }

    .carousel-item[data-position="2"],
    .carousel-item[data-position="-2"] {
        transform: translate(-50%, -50%) translateZ(-400px) scale(0.5);
    }

    .carousel-hint {
        display: none;
    }

    /* Mobile arrows */
    .carousel-arrow {
        width: 50px;
        height: 50px;
    }

    .carousel-arrow svg {
        width: 24px;
        height: 24px;
    }

    .carousel-arrow-prev {
        left: 20px;
    }

    .carousel-arrow-next {
        right: 20px;
    }
}

/* Scroll animations */
.scroll-animate:not(.project-card) {
    opacity: 0;
    transform: translateY(30px);
    transition: all 0.6s ease-out;
}

.scroll-animate.active:not(.project-card) {
    opacity: 1;
    transform: translateY(0);
}

/* Project kartlarda reveal sadece opacity ile calissin;
   boylece hover'daki scale transform'u ezilmez. */
.project-card.scroll-animate {
    opacity: 0;
    transition: transform 0.24s ease, box-shadow 0.24s ease, opacity 0.6s ease-out;
}

.project-card.scroll-animate.active {
    opacity: 1;
}
.profile-photo {
    width: 400px;
    height: 400px;
    border-radius: 50%;
    object-fit: cover;
    background: var(--gradient-2);
    box-shadow: var(--shadow-glow);
    animation: float 6s ease-in-out infinite, fadeIn 1s ease-in-out;
    border: 4px solid #fff;
}

/* Project detail modal */
.project-card[role="button"] {
    cursor: pointer;
}

.project-card[role="button"]:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 3px;
}

.project-detail-modal {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(10px);
    z-index: 11000;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.25s ease;
    padding: 1.2rem 1rem;
    overflow-y: auto;
}

.project-detail-modal.active {
    opacity: 1;
    visibility: visible;
}

.project-detail-panel {
    width: min(1100px, 100%);
    margin: 0 auto;
    background: var(--dark-secondary);
    border: 1px solid var(--dark-tertiary);
    border-radius: 16px;
    box-shadow: 0 30px 60px rgba(0, 0, 0, 0.45);
    padding: 1.4rem;
    display: flex;
    flex-direction: column;
    gap: 1.6rem;
    position: relative;
}

.project-detail-panel section {
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
}

.project-detail-close {
    position: absolute;
    top: 16px;
    right: 16px;
    border: 1px solid var(--dark-tertiary);
    background: var(--dark-bg);
    color: var(--text-primary);
    width: 40px;
    height: 40px;
    border-radius: 50%;
    font-size: 1.4rem;
    line-height: 1;
    cursor: pointer;
}

.project-detail-close:hover {
    border-color: var(--primary-color);
    color: var(--primary-color);
}

.project-detail-header {
    display: flex;
    flex-direction: column;
    gap: 0.7rem;
}

.project-detail-header h3 {
    font-size: 1.7rem;
    margin: 0;
}

.project-detail-header p {
    color: var(--text-secondary);
    font-size: 0.96rem;
    margin: 0;
}

.project-detail-kicker {
    display: inline-block;
    margin: 0;
    color: var(--primary-color);
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-size: 0.8rem;
}

.project-detail-video h4,
.project-detail-description h4,
.project-detail-grid h4,
.project-detail-gallery-wrap h4,
.project-detail-links-wrap h4 {
    margin: 0;
    font-size: 0.98rem;
    letter-spacing: 0.02em;
}

.project-video-wrapper {
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid var(--dark-tertiary);
    background: #000;
    aspect-ratio: 16 / 9;
}

.project-video-wrapper iframe {
    width: 100%;
    height: 100%;
    border: 0;
}

.project-detail-description p {
    color: var(--text-secondary);
    line-height: 1.55;
    margin: 0;
}

.project-detail-grid {
    display: grid;
    grid-template-columns: 1fr 1.25fr;
    gap: 0.8rem;
}

.project-detail-list {
    list-style: none;
    padding: 0;
    margin: 0.04rem 0 0;
}

.project-detail-list li {
    position: relative;
    padding-left: 1.2rem;
    margin-bottom: 0.18rem;
    color: var(--text-secondary);
}

.project-detail-list li:last-child {
    margin-bottom: 0;
}

.project-detail-list li::before {
    content: '•';
    color: var(--primary-color);
    position: absolute;
    left: 0;
}

.project-detail-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
}

.project-detail-grid h4 + .project-detail-tags {
    margin-top: 0.55rem;
}

.project-detail-chip {
    background: var(--dark-bg);
    border: 1px solid var(--dark-tertiary);
    color: var(--text-primary);
    padding: 0.45rem 0.8rem;
    border-radius: 999px;
    font-size: 0.88rem;
}

.project-detail-gallery {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 0.1rem;
}

.project-gallery-item {
    margin: 2px;
    padding: 0;
    border-radius: 10px;
    overflow: hidden;
    border: 1px solid var(--dark-tertiary);
    background: var(--dark-bg);
    min-height: 100px;
    aspect-ratio: 16 / 9;
    cursor: pointer;
    transition: transform 0.2s ease, border-color 0.2s ease;
}

.project-gallery-item:hover {
    transform: translateY(-2px);
    border-color: var(--primary-color);
}

.project-gallery-item:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}

.project-gallery-item img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    max-width: 100%;
}

.project-detail-links {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.project-detail-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    text-decoration: none;
    width: 44px;
    height: 44px;
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.95), rgba(236, 72, 153, 0.95));
    border: 1px solid rgba(248, 250, 252, 0.28);
    color: #fff;
    padding: 0;
    border-radius: 12px;
    box-shadow: 0 6px 16px rgba(99, 102, 241, 0.3);
    transition: all 0.2s ease;
}

.project-detail-link:hover {
    color: #fff;
    border-color: rgba(248, 250, 252, 0.6);
    transform: translateY(-2px) scale(1.05);
    box-shadow: 0 10px 22px rgba(236, 72, 153, 0.35);
}

.project-detail-link svg {
    width: 20px;
    height: 20px;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.project-lightbox {
    position: fixed;
    inset: 0;
    background: rgba(2, 6, 23, 0.9);
    backdrop-filter: blur(10px);
    z-index: 12000;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.2s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}

.project-lightbox.active {
    opacity: 1;
    visibility: visible;
}

.project-lightbox-image {
    max-width: min(1400px, 96vw);
    max-height: 88vh;
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.35);
    box-shadow: 0 18px 60px rgba(0, 0, 0, 0.55);
}

.project-lightbox-close {
    position: fixed;
    top: 16px;
    right: 20px;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    border: 1px solid rgba(248, 250, 252, 0.4);
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.95), rgba(236, 72, 153, 0.95));
    color: #fff;
    font-size: 1.5rem;
    line-height: 1;
    cursor: pointer;
}

@media (max-width: 900px) {
    .project-detail-panel {
        padding: 1rem;
    }

    .project-detail-header h3 {
        font-size: 1.5rem;
        padding-right: 2.2rem;
    }

    .project-detail-grid {
        grid-template-columns: 1fr;
    }
}

/* Reset & Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --primary-color: #6366f1;
    --secondary-color: #8b5cf6;
    --accent-color: #ec4899;
    --dark-bg: #0f172a;
    --dark-secondary: #1e293b;
    --dark-tertiary: #334155;
    --text-primary: #f1f5f9;
    --text-secondary: #cbd5e1;
    --text-muted: #94a3b8;
    --gradient-1: linear-gradient(135deg, #6366f1 0%, #8b5cf6 50%, #ec4899 100%);
    --gradient-2: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
    --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.1);
    --shadow-md: 0 4px 16px rgba(0, 0, 0, 0.2);
    --shadow-lg: 0 8px 32px rgba(0, 0, 0, 0.3);
    --shadow-glow: 0 0 20px rgba(99, 102, 241, 0.3);
}

html {
    scroll-behavior: smooth;
}

body {
    background-color: var(--dark-bg);
    color: var(--text-primary);
    line-height: 1.6;
    overflow-x: hidden;
    font-family: "Inter", "Segoe UI", Roboto, Arial, sans-serif;
}

html,
body {
    cursor: auto;
}

a,
button,
[role="button"],
.project-card,
.project-card-action-link,
.project-detail-link,
.project-gallery-item,
.carousel-arrow,
.dot,
.accordion-header,
.social-link,
.btn,
input[type="submit"],
input[type="button"] {
    cursor: pointer;
}

@media (hover: none), (pointer: coarse) {
    html,
    body,
    a,
    button,
    [role="button"],
    .project-card,
    .project-card-action-link,
    .project-detail-link,
    .project-gallery-item,
    .carousel-arrow,
    .dot,
    .accordion-header,
    .social-link,
    .btn,
    input[type="submit"],
    input[type="button"] {
        cursor: auto !important;
    }
}

.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
}

/* Navigation Bar */
.navbar {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    background: rgba(15, 23, 42, 0.9);
    backdrop-filter: blur(10px);
    padding: 1rem 0;
    box-shadow: var(--shadow-md);
    transition: all 0.3s ease;
    z-index: 1000;
}

.nav-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.logo {
    font-size: 1.2rem;
    font-weight: 700;
    letter-spacing: 0.02em;
    color: var(--text-primary);
    white-space: nowrap;
}

.navbar.scrolled {
    padding: 0.5rem 0;
    background: rgba(15, 23, 42, 0.95);
}


.nav-menu {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-link {
    color: var(--text-secondary);
    text-decoration: none;
    font-weight: 500;
    transition: all 0.3s ease;
    position: relative;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -5px;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--gradient-1);
    transition: width 0.3s ease;
}

.nav-link:hover {
    color: var(--text-primary);
}

.nav-link:hover::after {
    width: 100%;
}

.nav-link.active {
    color: var(--primary-color);
}

.hamburger {
    display: none;
    flex-direction: column;
    cursor: pointer;
    gap: 4px;
}

.hamburger span {
    width: 25px;
    height: 3px;
    background: var(--text-primary);
    border-radius: 3px;
    transition: all 0.3s ease;
}

/* Hero Section */
.hero {
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 120px 20px 80px;
    max-width: 1200px;
    margin: 0 auto;
    gap: 60px;
}

.hero-content {
    flex: 1;
    max-width: 600px;
}

.hero-title {
    font-size: 3.5rem;
    font-weight: 800;
    margin-bottom: 1rem;
    line-height: 1.2;
}

.gradient-text {
    background: var(--gradient-1);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.hero-subtitle {
    font-size: 1.5rem;
    color: var(--text-secondary);
    margin-bottom: 1rem;
}

.hero-description {
    font-size: 1.1rem;
    color: var(--text-muted);
    margin-bottom: 2rem;
}

.hero-buttons {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.btn {
    padding: 12px 30px;
    border-radius: 8px;
    text-decoration: none;
    font-weight: 600;
    transition: all 0.3s ease;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    display: inline-block;
}

.btn-primary {
    background: var(--gradient-1);
    color: white;
    box-shadow: var(--shadow-glow);
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 0 30px rgba(99, 102, 241, 0.5);
}

.btn-secondary {
    background: transparent;
    color: var(--text-primary);
    border: 2px solid var(--primary-color);
}

.btn-secondary:hover {
    background: var(--primary-color);
    transform: translateY(-2px);
}

.btn-full {
    width: 100%;
    text-align: center;
}

.hero-image {
    flex: 1;
    display: flex;
    justify-content: center;
    align-items: center;
}

.image-placeholder {
    width: 400px;
    height: 400px;
    /*background: var(--gradient-2);*/
    /*border-radius: 50%;*/
    position: relative;
    /*box-shadow: var(--shadow-glow);*/
    animation: float 100s ease-in-out infinite;
}

@keyframes float {
    0%, 100% { transform: translateY(0px); }
    50% { transform: translateY(-20px); }
}

.floating-icon {
    position: absolute;
    font-size: 3rem;
    animation: rotate 20s linear infinite;
}

.icon-1 {
    top: 10%;
    left: 10%;
    animation: float 3s ease-in-out infinite;
}

.icon-2 {
    top: 10%;
    right: 10%;
    animation: float 4s ease-in-out infinite;
}

.icon-3 {
    bottom: 10%;
    left: 10%;
    animation: float 5s ease-in-out infinite;
}

.icon-4 {
    bottom: 10%;
    right: 10%;
    animation: float 3.5s ease-in-out infinite;
}

/* Animations */
.animate-fade-in {
    animation: fadeIn 1s ease-out;
}

.animate-fade-in-delay {
    animation: fadeIn 1s ease-out 0.2s backwards;
}

.animate-fade-in-delay-2 {
    animation: fadeIn 1s ease-out 0.4s backwards;
}

.animate-fade-in-delay-3 {
    animation: fadeIn 1s ease-out 0.6s backwards;
}

.animate-slide-in {
    animation: slideIn 1s ease-out 0.3s backwards;
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes slideIn {
    from {
        opacity: 0;
        transform: translateX(50px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

/* Section Styles */
section {
    padding: 100px 20px;
}

.section-title {
    font-size: 2.5rem;
    text-align: center;
    margin-bottom: 4rem;
    position: relative;
}

.section-title::after {
    content: '';
    position: absolute;
    bottom: -10px;
    left: 50%;
    transform: translateX(-50%);
    width: 100px;
    height: 4px;
    background: var(--gradient-1);
    border-radius: 2px;
}

/* About Section */
.about {
    background: var(--dark-secondary);
}

/* Experience Section */
.experience {
    background: var(--dark-bg);
}

.experience-grid {
    display: grid;
    grid-template-columns: repeat(12, minmax(0, 1fr));
    gap: 1.25rem;
}

.experience-card {
    background: linear-gradient(160deg, rgba(30, 41, 59, 0.95), rgba(15, 23, 42, 0.95));
    border: 1px solid var(--dark-tertiary);
    border-radius: 16px;
    padding: 1.2rem;
    transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;
}

.experience-card:hover {
    transform: translateY(-4px);
    border-color: rgba(139, 92, 246, 0.7);
    box-shadow: 0 10px 28px rgba(99, 102, 241, 0.2);
}

.experience-card--timeline {
    grid-column: span 6;
    display: grid;
    grid-template-columns: auto 1fr;
    column-gap: 0.9rem;
    row-gap: 0.45rem;
}

.experience-card--timeline .experience-icon {
    grid-row: 1 / span 4;
}

.experience-card--featured {
    grid-column: span 6;
    position: relative;
    overflow: hidden;
}

.experience-card--featured::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    padding: 1px;
    background: linear-gradient(120deg, rgba(99, 102, 241, 0.85), rgba(139, 92, 246, 0.8), rgba(236, 72, 153, 0.7));
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    opacity: 0.9;
    pointer-events: none;
}

.experience-top-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.75rem;
    margin-bottom: 0.7rem;
}

.experience-card--compact {
    grid-column: span 12;
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.9rem;
    align-items: start;
}

.experience-compact-body {
    display: grid;
    gap: 0.34rem;
}

.experience-icon {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: var(--gradient-1);
    font-size: 1.2rem;
    box-shadow: 0 8px 18px rgba(99, 102, 241, 0.3);
}

.experience-meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.7rem;
    flex-wrap: wrap;
}

.experience-company {
    color: var(--text-primary);
    font-size: 1.08rem;
    font-weight: 700;
}

.experience-role {
    color: #c4b5fd;
    font-weight: 600;
    margin: 0;
}

.experience-project {
    color: #93c5fd;
    margin: 0;
    font-size: 0.95rem;
}

.experience-date {
    color: var(--text-muted);
    font-size: 0.86rem;
}

.experience-description {
    color: var(--text-secondary);
    margin: 0;
}

.experience-description a {
    color: #93c5fd; /* Light blue for links */
    text-decoration: underline;
    transition: color 0.3s ease;
}

.experience-description a:hover {
    color: #c4b5fd; /* Lighter purple on hover */
}

.about-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 60px;
    align-items: center;
}

.profile-card {
    position: relative;
    width: 300px;
    height: 300px;
    margin: 0 auto;
}

.profile-image {
    width: 100%;
    height: 100%;
    background: var(--gradient-2);
    border-radius: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 8rem;
    box-shadow: var(--shadow-lg);
    position: relative;
    z-index: 2;
}

.card-glow {
    position: absolute;
    top: 20px;
    left: 20px;
    right: -20px;
    bottom: -20px;
    background: var(--gradient-1);
    border-radius: 20px;
    filter: blur(20px);
    opacity: 0.3;
    z-index: 1;
}

.about-text h3 {
    font-size: 2rem;
    margin-bottom: 1.5rem;
    color: var(--text-primary);
}

.about-text p {
    color: var(--text-secondary);
    margin-bottom: 1rem;
    font-size: 1.1rem;
}

.about-stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2rem;
    margin-top: 3rem;
}
/*.skills{*/
/*    background: var(--dar);*/
/*}*/

.stat-item {
    text-align: center;
    padding: 1.5rem;
    background: var(--dark-tertiary);
    border-radius: 12px;
    transition: transform 0.3s ease;
}

.stat-item:hover {
    transform: translateY(-5px);
}

.stat-item h4 {
    font-size: 2.5rem;
    background: var(--gradient-1);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 0.5rem;
}

.stat-item p {
    color: var(--text-muted);
    font-size: 0.9rem;
}

/* Skills Section */
.skills-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.skill-card {
    background: var(--dark-secondary);
    padding: 2rem;
    border-radius: 16px;
    text-align: center;
    transition: all 0.3s ease;
    border: 1px solid transparent;
}

.skill-card:hover {
    transform: translateY(-10px);
    border-color: var(--primary-color);
    box-shadow: var(--shadow-glow);
}

.skill-icon {
    font-size: 3rem;
    margin-bottom: 1rem;
}

.skill-card h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
    color: var(--text-primary);
}

.skill-card p {
    color: var(--text-muted);
    margin-bottom: 1.5rem;
}

.skill-bar {
    width: 100%;
    height: 8px;
    background: var(--dark-tertiary);
    border-radius: 4px;
    overflow: hidden;
}

.skill-progress {
    height: 100%;
    background: var(--gradient-1);
    border-radius: 4px;
    width: 0;
    transition: width 1s ease-out;
}

/* Projects Section */
.projects {
    background: var(--dark-secondary);
}

.projects-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 2rem;
    overflow: visible;
}

.project-card {
    background: var(--dark-bg);
    border-radius: 16px;
    overflow: hidden;
    border: 1px solid var(--dark-tertiary);
    position: relative;
    isolation: isolate;
    transform: translateZ(0) scale(1);
    transform-origin: center center;
    will-change: transform;
    transition: transform 0.24s ease, box-shadow 0.24s ease;
}

.project-card::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    padding: 2px;
    background: linear-gradient(120deg, #6366f1, #8b5cf6, #ec4899, #6366f1);
    background-size: 240% 240%;
    opacity: 0;
    z-index: 3;
    pointer-events: none;
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask-composite: exclude;
    transition: opacity 0.25s ease;
}

.project-card > * {
    position: relative;
    z-index: 1;
}

.project-card:hover {
    transform: translateZ(0) scale(1.05);
    z-index: 30;
    box-shadow: 0 10px 26px rgba(99, 102, 241, 0.22);
}

.project-card:hover::before {
    opacity: 1;
    animation: projectOutlineFlow 0.95s linear infinite;
}

@keyframes projectOutlineFlow {
    0% {
        background-position: 0% 50%;
    }
    100% {
        background-position: 200% 50%;
    }
}

.project-image {
    position: relative;
    height: 250px;
    background: var(--dark-tertiary);
    overflow: hidden;
}

.project-placeholder {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 6rem;
    background: var(--gradient-2);
}

.project-image {
    position: relative;
    width: 100%;
    height: 220px;
    overflow: hidden;
    border-radius: 12px;
}

.project-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    position: relative;
    z-index: 0;
}

.project-card[data-project-id="nuts-and-bolts"] .project-image img {
    object-position: center 25%;
}

.project-card[data-project-id="city-jam"] .project-image img {
    object-position: center 60%;
}

.project-card[data-project-id="army-runner"] .project-image img {
    object-position: center 40%;
}

/* Ball Blast cover alignment: ikinci degeri degistirerek yukari/asagi ayarlayabilirsin. */
.project-card[data-project-id="ball-blast-clone"] .project-image img {
    object-position: center 20%;
}

.project-card-links {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    display: flex;
    justify-content: flex-end;
    gap: 0.6rem;
    padding: 0.7rem 0.8rem;
    background: linear-gradient(to top, rgba(15, 23, 42, 0.98), rgba(15, 23, 42, 0.35), rgba(15, 23, 42, 0));
    z-index: 2;
}

.project-card-action-link {
    width: 40px;
    height: 40px;
    border-radius: 10px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.95), rgba(236, 72, 153, 0.95));
    border: 1px solid rgba(248, 250, 252, 0.28);
    color: #fff;
    box-shadow: 0 6px 16px rgba(99, 102, 241, 0.35);
    transition: all 0.22s ease;
}

.project-card-action-link:hover {
    color: #fff;
    border-color: rgba(248, 250, 252, 0.55);
    transform: translateY(-2px) scale(1.04);
    box-shadow: 0 10px 22px rgba(236, 72, 153, 0.35);
}

.project-card-action-link:focus-visible {
    outline: 2px solid #f8fafc;
    outline-offset: 2px;
}

.project-card-action-link svg {
    width: 18px;
    height: 18px;
}

.project-overlay {
    position: absolute;
    inset: 0; /* top:0, right:0, bottom:0, left:0 */
    width: 100%;
    height: 100%;
}

.project-overlay img {
    position: absolute;
    width: 100%;
    height: 100%;
    object-fit: cover; /* genişliği ve yüksekliği tam doldurur */
    object-position: center;
}

.project-links {
    position: absolute;
    bottom: 10px;
    left: 10px;
    z-index: 1;
    display: flex;
    gap: 8px;
}

.project-placeholder {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 2rem;
    opacity: 0.2;
}


.project-links {
    display: flex;
    gap: 1rem;
}

.project-link {
    padding: 10px 20px;
    background: white;
    color: var(--primary-color);
    text-decoration: none;
    border-radius: 8px;
    font-weight: 600;
    transition: all 0.3s ease;
}

.project-link:hover {
    transform: scale(1.1);
}

.project-content {
    padding: 1.5rem;
}

.project-content h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
    color: var(--text-primary);
}

.project-content p {
    color: var(--text-secondary);
    margin-bottom: 1.5rem;
    font-size: 0.95rem;
}

.project-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.tag {
    padding: 6px 12px;
    background: var(--dark-tertiary);
    color: var(--primary-color);
    border-radius: 20px;
    font-size: 0.85rem;
    font-weight: 500;
}

/* Testimonials / Carousel Section */
.testimonials {
    background: var(--dark-bg);
    overflow: hidden;
    position: relative;
}

.section-subtitle {
    text-align: center;
    color: var(--text-muted);
    font-size: 1.1rem;
    margin-top: -2rem;
    margin-bottom: 4rem;
}

.carousel-3d-container {
    position: relative;
    width: 100%;
    height: 600px;
    perspective: 2000px;
    margin-top: 3rem;
}

.carousel-3d {
    position: relative;
    width: 100%;
    height: 100%;
    transform-style: preserve-3d;
    transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

.carousel-item {
    position: absolute;
    width: 500px;
    height: 450px;
    left: 50%;
    top: 50%;
    transform-style: preserve-3d;
    transition: all 0.6s cubic-bezier(0.4, 0, 0.2, 1);
    cursor: pointer;
}

.carousel-card {
    width: 100%;
    height: 100%;
    background: var(--dark-secondary);
    border-radius: 20px;
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    border: 1px solid var(--dark-tertiary);
    transition: all 0.3s ease;
    transform-style: preserve-3d;
    backface-visibility: hidden;
}

.carousel-item.active .carousel-card {
    border-color: var(--primary-color);
    box-shadow: 0 20px 60px rgba(99, 102, 241, 0.4);
}

.carousel-item:not(.active) .carousel-card {
    opacity: 0.6;
    filter: blur(1px);
}

.carousel-item:hover:not(.active) .carousel-card {
    opacity: 0.8;
    transform: scale(1.02);
}

.card-image {
    position: relative;
    height: 200px;
    background: var(--gradient-2);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.card-image::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.2) 0%, rgba(139, 92, 246, 0.2) 100%);
}

.image-icon {
    font-size: 5rem;
    position: relative;
    z-index: 2;
    animation: float 3s ease-in-out infinite;
}

.card-badge {
    position: absolute;
    top: 20px;
    right: 20px;
    background: rgba(255, 255, 255, 0.2);
    backdrop-filter: blur(10px);
    padding: 8px 16px;
    border-radius: 20px;
    font-size: 1.2rem;
    z-index: 3;
}

.card-content {
    padding: 2rem;
    position: relative;
}

.quote-icon {
    font-size: 4rem;
    color: var(--primary-color);
    opacity: 0.3;
    position: absolute;
    top: 0;
    left: 1rem;
    line-height: 1;
}

.testimonial-text {
    color: var(--text-secondary);
    font-size: 1rem;
    line-height: 1.7;
    margin-bottom: 1.5rem;
    position: relative;
    z-index: 2;
    margin-top: 1rem;
}

.testimonial-author {
    border-top: 1px solid var(--dark-tertiary);
    padding-top: 1rem;
}

.testimonial-author h4 {
    color: var(--text-primary);
    font-size: 1.2rem;
    margin-bottom: 0.25rem;
}

.testimonial-author p {
    color: var(--text-muted);
    font-size: 0.9rem;
}

/* Carousel Navigation Dots */
.carousel-dots {
    position: absolute;
    bottom: 30px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    gap: 12px;
    z-index: 10;
}

.dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: var(--dark-tertiary);
    cursor: pointer;
    transition: all 0.3s ease;
    border: 2px solid transparent;
}

.dot:hover {
    background: var(--text-muted);
    transform: scale(1.2);
}

.dot.active {
    background: var(--gradient-1);
    border-color: var(--primary-color);
    transform: scale(1.3);
    box-shadow: 0 0 10px rgba(99, 102, 241, 0.5);
}

/* Carousel Arrow Buttons */
.carousel-arrow {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: var(--dark-secondary);
    border: 2px solid var(--dark-tertiary);
    color: var(--text-primary);
    cursor: pointer;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
    backdrop-filter: blur(10px);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

.carousel-arrow:hover {
    background: var(--gradient-1);
    border-color: var(--primary-color);
    transform: translateY(-50%) scale(1.1);
    box-shadow: 0 8px 24px rgba(99, 102, 241, 0.4);
}

.carousel-arrow:active {
    transform: translateY(-50%) scale(0.95);
}

.carousel-arrow svg {
    width: 30px;
    height: 30px;
    stroke-width: 3;
}

.carousel-arrow-prev {
    left: 50px;
}

.carousel-arrow-next {
    right: 50px;
}

/* Arrow animation on hover */
.carousel-arrow-prev:hover svg {
    animation: arrowBounceLeft 0.6s ease-in-out infinite;
}

.carousel-arrow-next:hover svg {
    animation: arrowBounceRight 0.6s ease-in-out infinite;
}

@keyframes arrowBounceLeft {
    0%, 100% { transform: translateX(0); }
    50% { transform: translateX(-5px); }
}

@keyframes arrowBounceRight {
    0%, 100% { transform: translateX(0); }
    50% { transform: translateX(5px); }
}

/* Carousel Hint */
.carousel-hint {
    position: absolute;
    bottom: 80px;
    left: 50%;
    transform: translateX(-50%);
    text-align: center;
    opacity: 0.6;
    animation: pulse 2s ease-in-out infinite;
}

.hint-icon {
    font-size: 2rem;
    display: block;
    margin-bottom: 0.5rem;
}

.carousel-hint p {
    color: var(--text-muted);
    font-size: 0.9rem;
}

@keyframes pulse {
    0%, 100% { opacity: 0.4; transform: translateX(-50%) translateY(0); }
    50% { opacity: 0.8; transform: translateX(-50%) translateY(-5px); }
}

/* 3D Carousel Positioning */
.carousel-item[data-position="0"] {
    transform: translate(-50%, -50%) translateZ(0) scale(1);
    z-index: 5;
    opacity: 1;
}

.carousel-item[data-position="1"] {
    transform: translate(-30%, -50%) translateZ(-300px) translateX(400px) scale(0.8);
    z-index: 3;
    opacity: 0.7;
}

.carousel-item[data-position="-1"] {
    transform: translate(-70%, -50%) translateZ(-300px) translateX(-400px) scale(0.8);
    z-index: 3;
    opacity: 0.7;
}

.carousel-item[data-position="2"] {
    transform: translate(-20%, -50%) translateZ(-500px) translateX(600px) scale(0.6);
    z-index: 1;
    opacity: 0.4;
}

.carousel-item[data-position="-2"] {
    transform: translate(-80%, -50%) translateZ(-500px) translateX(-600px) scale(0.6);
    z-index: 1;
    opacity: 0.4;
}

/* Modal Overlay & Wrapper */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.85);
    backdrop-filter: blur(10px);
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    visibility: hidden;
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.modal-overlay.active {
    opacity: 1;
    visibility: visible;
}

.modal-wrapper {
    position: relative;
    width: 90%;
    max-width: 800px;
    max-height: 90vh;
    background: var(--dark-secondary);
    border-radius: 24px;
    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.5);
    border: 1px solid var(--dark-tertiary);
    transform: scale(0.9) translateY(30px);
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
}

.modal-overlay.active .modal-wrapper {
    transform: scale(1) translateY(0);
}

/* Modal Close Button */
.modal-close {
    position: absolute;
    top: 20px;
    right: 20px;
    width: 45px;
    height: 45px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.1);
    border: 2px solid var(--dark-tertiary);
    color: var(--text-primary);
    cursor: pointer;
    z-index: 10;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
    backdrop-filter: blur(10px);
}

.modal-close:hover {
    background: var(--gradient-1);
    border-color: var(--primary-color);
    transform: rotate(90deg) scale(1.1);
    box-shadow: 0 4px 16px rgba(99, 102, 241, 0.4);
}

.modal-close svg {
    width: 24px;
    height: 24px;
}

/* Modal Content */
.modal-content {
    max-height: 90vh;
    overflow-y: auto;
    padding: 0;
}

/* Custom Scrollbar for Modal */
.modal-content::-webkit-scrollbar {
    width: 8px;
}

.modal-content::-webkit-scrollbar-track {
    background: var(--dark-tertiary);
    border-radius: 4px;
}

.modal-content::-webkit-scrollbar-thumb {
    background: var(--primary-color);
    border-radius: 4px;
}

.modal-content::-webkit-scrollbar-thumb:hover {
    background: var(--secondary-color);
}

/* Modal Header */
.modal-header {
    background: var(--gradient-2);
    padding: 3rem 3rem 2rem;
    display: flex;
    align-items: center;
    gap: 2rem;
    position: relative;
}

.modal-header::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.2) 0%, rgba(139, 92, 246, 0.2) 100%);
}

.modal-avatar {
    position: relative;
    width: 120px;
    height: 120px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.2);
    backdrop-filter: blur(10px);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 4rem;
    border: 3px solid rgba(255, 255, 255, 0.3);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
    z-index: 2;
    animation: modalAvatarPulse 2s ease-in-out infinite;
}

@keyframes modalAvatarPulse {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.05); }
}

.modal-header-info {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    position: relative;
    z-index: 2;
}

.modal-header-info h2 {
    font-size: 2.5rem;
    margin: 0;
    color: var(--text-primary);
}

.modal-header-info p {
    font-size: 1.2rem;
    color: var(--text-secondary);
    margin: 0;
}

.modal-rating {
    font-size: 1.5rem;
    letter-spacing: 4px;
    margin: 0;
}

/* Modal Body */
.modal-body {
    padding: 3rem;
    position: relative;
}

.quote-mark {
    font-size: 6rem;
    color: var(--primary-color);
    opacity: 0.2;
    line-height: 1;
    position: absolute;
    top: 2rem;
    left: 2rem;
}

.quote-mark-end {
    top: auto;
    bottom: 2rem;
    left: auto;
    right: 2rem;
    transform: rotate(180deg);
}

.modal-testimonial {
    font-size: 1.3rem;
    line-height: 1.8;
    color: var(--text-secondary);
    text-align: center;
    position: relative;
    z-index: 2;
    padding: 0 2rem;
}

/* Modal Footer */
.modal-footer {
    padding: 2rem 3rem 3rem;
    background: var(--dark-bg);
    border-top: 1px solid var(--dark-tertiary);
}

.modal-info-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.modal-info-item {
    display: flex;
    align-items: flex-start;
    gap: 1rem;
    padding: 1.5rem;
    background: var(--dark-secondary);
    border-radius: 12px;
    border: 1px solid var(--dark-tertiary);
    transition: all 0.3s ease;
}

.modal-info-item:hover {
    transform: translateY(-5px);
    border-color: var(--primary-color);
    box-shadow: 0 8px 16px rgba(99, 102, 241, 0.2);
}

.info-icon {
    font-size: 2rem;
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--gradient-1);
    border-radius: 12px;
    flex-shrink: 0;
}

.info-content h4 {
    font-size: 0.9rem;
    color: var(--text-muted);
    margin-bottom: 0.25rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.info-content p {
    font-size: 1.1rem;
    color: var(--text-primary);
    font-weight: 600;
}

/* Modal Technologies */
.modal-technologies {
    margin-top: 2rem;
}

.modal-technologies h4 {
    font-size: 1.1rem;
    color: var(--text-primary);
    margin-bottom: 1rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.tech-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.75rem;
}

.tech-tag {
    padding: 10px 20px;
    background: var(--gradient-2);
    color: var(--primary-color);
    border-radius: 20px;
    font-size: 0.95rem;
    font-weight: 600;
    border: 1px solid var(--primary-color);
    box-shadow: 0 4px 12px rgba(99, 102, 241, 0.2);
    transition: all 0.3s ease;
    cursor: default;
}

.tech-tag:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 20px rgba(99, 102, 241, 0.4);
}

/* Modal Accordion */
.modal-accordion {
    margin-top: 2.5rem;
}

.modal-accordion h4 {
    font-size: 1.1rem;
    color: var(--text-primary);
    margin-bottom: 1rem;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.accordion-container {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.accordion-item {
    background: var(--dark-secondary);
    border: 1px solid var(--dark-tertiary);
    border-radius: 12px;
    overflow: hidden;
    transition: all 0.3s ease;
}

.accordion-item.active {
    border-color: var(--primary-color);
    box-shadow: 0 4px 16px rgba(99, 102, 241, 0.2);
}

.accordion-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1.25rem 1.5rem;
    cursor: pointer;
    user-select: none;
    transition: all 0.3s ease;
    background: transparent;
}

.accordion-header:hover {
    background: rgba(99, 102, 241, 0.1);
}

.accordion-item.active .accordion-header {
    background: rgba(99, 102, 241, 0.15);
}

.accordion-title {
    display: flex;
    align-items: center;
    gap: 1rem;
    flex: 1;
}

.accordion-icon {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--gradient-1);
    border-radius: 10px;
    font-size: 1.3rem;
    flex-shrink: 0;
}

.accordion-title h5 {
    font-size: 1.1rem;
    color: var(--text-primary);
    margin: 0;
}

.accordion-arrow {
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--text-secondary);
    transition: transform 0.3s ease;
}

.accordion-item.active .accordion-arrow {
    transform: rotate(180deg);
    color: var(--primary-color);
}

.accordion-arrow svg {
    width: 20px;
    height: 20px;
}

.accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.accordion-item.active .accordion-content {
    max-height: 1000px;
}

.accordion-body {
    padding: 0 1.5rem 1.5rem;
    color: var(--text-secondary);
    line-height: 1.7;
}

.accordion-body p {
    margin-bottom: 1rem;
}

.accordion-body ul {
    list-style: none;
    padding: 0;
    margin: 1rem 0;
}

.accordion-body ul li {
    padding: 0.5rem 0;
    padding-left: 1.5rem;
    position: relative;
}

.accordion-body ul li::before {
    content: '▹';
    position: absolute;
    left: 0;
    color: var(--primary-color);
    font-size: 1.2rem;
}

.accordion-body ul li strong {
    color: var(--text-primary);
}

.accordion-highlight {
    background: rgba(99, 102, 241, 0.1);
    border-left: 3px solid var(--primary-color);
    padding: 1rem 1.5rem;
    margin: 1rem 0;
    border-radius: 8px;
}

.accordion-highlight p {
    margin: 0;
    color: var(--text-primary);
    font-weight: 500;
}

/* Modal Responsive */
@media (max-width: 768px) {
    .modal-wrapper {
        width: 95%;
        max-height: 95vh;
        border-radius: 16px;
    }

    .modal-header {
        flex-direction: column;
        text-align: center;
        padding: 2rem 1.5rem 1.5rem;
    }

    .modal-avatar {
        width: 100px;
        height: 100px;
        font-size: 3rem;
    }

    .modal-header-info h2 {
        font-size: 1.8rem;
    }

    .modal-body {
        padding: 2rem 1.5rem;
    }

    .modal-testimonial {
        font-size: 1.1rem;
        padding: 0 1rem;
    }

    .modal-footer {
        padding: 1.5rem;
    }

    .modal-info-grid {
        grid-template-columns: 1fr;
        gap: 1rem;
    }

    .modal-close {
        width: 40px;
        height: 40px;
        top: 15px;
        right: 15px;
    }

    .modal-close svg {
        width: 20px;
        height: 20px;
    }

    .quote-mark {
        font-size: 4rem;
        top: 1rem;
        left: 1rem;
    }

    .quote-mark-end {
        bottom: 1rem;
        right: 1rem;
    }
}


/* Contact Section */
.contact-content {
    display: flex;
    gap: 3rem;
    align-items: center;
    justify-content: center;
}

.contact-info h3 {
    font-size: 2rem;
    margin-bottom: 1rem;
}

.contact-info > p {
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

.contact-details {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    margin-bottom: 2rem;
}

.contact-item {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 1rem;
    background: var(--dark-secondary);
    border-radius: 12px;
    transition: transform 0.3s ease;
}

.contact-item:hover {
    transform: translateX(10px);
}

.contact-icon {
    font-size: 2rem;
    width: 60px;
    height: 60px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--gradient-1);
    border-radius: 12px;
}

.contact-item h4 {
    color: var(--text-primary);
    margin-bottom: 0.25rem;
}

.contact-item p {
    color: var(--text-muted);
    font-size: 0.9rem;
}

.social-links {
    display: flex;
    gap: 1rem;
}

.social-link {
    width: 50px;
    height: 50px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: var(--dark-secondary);
    border-radius: 12px;
    color: var(--text-primary);
    transition: all 0.3s ease;
}

.social-link:hover {
    background: var(--gradient-1);
    transform: translateY(-5px);
}

.social-link svg {
    width: 24px;
    height: 24px;
}

.contact-form {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.form-group {
    display: flex;
    flex-direction: column;
}

.form-group input,
.form-group textarea {
    padding: 1rem;
    background: var(--dark-secondary);
    border: 2px solid var(--dark-tertiary);
    border-radius: 8px;
    color: var(--text-primary);
    font-size: 1rem;
    font-family: inherit;
    transition: all 0.3s ease;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: var(--shadow-glow);
}

.form-group textarea {
    resize: vertical;
    min-height: 120px;
}

/* Footer */
.footer {
    background: var(--dark-secondary);
    padding: 2rem;
    text-align: center;
    color: var(--text-muted);
}

.footer p {
    margin: 0.5rem 0;
}

/* Responsive Design */
@media (max-width: 968px) {
    .hero {
        flex-direction: column;
        text-align: center;
        padding-top: 100px;
    }

    .hero-content {
        max-width: 100%;
    }

    .hero-title {
        font-size: 2.5rem;
    }

    .hero-buttons {
        justify-content: center;
    }

    .image-placeholder {
        width: 300px;
        height: 300px;
    }

    .about-content {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .about-stats {
        grid-template-columns: repeat(3, 1fr);
    }

    .contact-content {
        grid-template-columns: 1fr;
    }

    .experience-card--timeline,
    .experience-card--featured,
    .experience-card--compact {
        grid-column: span 12;
    }

    .nav-menu {
        position: fixed;
        left: -100%;
        top: 70px;
        flex-direction: column;
        background: rgba(15, 23, 42, 0.98);
        width: 100%;
        text-align: center;
        transition: left 0.3s;
        box-shadow: var(--shadow-lg);
        padding: 2rem 0;
    }

    .nav-menu.active {
        left: 0;
    }

    .hamburger {
        display: flex;
    }

    .hamburger.active span:nth-child(1) {
        transform: rotate(45deg) translate(8px, 8px);
    }

    .hamburger.active span:nth-child(2) {
        opacity: 0;
    }

    .hamburger.active span:nth-child(3) {
        transform: rotate(-45deg) translate(8px, -8px);
    }
}

@media (max-width: 768px) {
    .hero-title {
        font-size: 2rem;
    }

    .hero-subtitle {
        font-size: 1.2rem;
    }

    .section-title {
        font-size: 2rem;
    }

    .about-stats {
        grid-template-columns: 1fr;
    }

    .skills-grid {
        grid-template-columns: 1fr;
    }

    .projects-grid {
        grid-template-columns: 1fr;
    }

    section {
        padding: 60px 20px;
    }

    /* Carousel mobile responsive */
    .carousel-3d-container {
        height: 500px;
        perspective: 1000px;
    }

    .carousel-item {
        width: 90%;
        max-width: 350px;
        height: 400px;
    }

    .carousel-item[data-position="1"],
    .carousel-item[data-position="-1"] {
        transform: translate(-50%, -50%) translateZ(-200px) scale(0.7);
    }

    .carousel-item[data-position="2"],
    .carousel-item[data-position="-2"] {
        transform: translate(-50%, -50%) translateZ(-400px) scale(0.5);
    }

    .carousel-hint {
        display: none;
    }

    /* Mobile arrows */
    .carousel-arrow {
        width: 50px;
        height: 50px;
    }

    .carousel-arrow svg {
        width: 24px;
        height: 24px;
    }

    .carousel-arrow-prev {
        left: 20px;
    }

    .carousel-arrow-next {
        right: 20px;
    }
}

/* Scroll animations */
.scroll-animate:not(.project-card) {
    opacity: 0;
    transform: translateY(30px);
    transition: all 0.6s ease-out;
}

.scroll-animate.active:not(.project-card) {
    opacity: 1;
    transform: translateY(0);
}

/* Project kartlarda reveal sadece opacity ile calissin;
   boylece hover'daki scale transform'u ezilmez. */
.project-card.scroll-animate {
    opacity: 0;
    transition: transform 0.24s ease, box-shadow 0.24s ease, opacity 0.6s ease-out;
}

.project-card.scroll-animate.active {
    opacity: 1;
}
.profile-photo {
    width: 400px;
    height: 400px;
    border-radius: 50%;
    object-fit: cover;
    background: var(--gradient-2);
    box-shadow: var(--shadow-glow);
    animation: float 6s ease-in-out infinite, fadeIn 1s ease-in-out;
    border: 4px solid #fff;
}

/* Project detail modal */
.project-card[role="button"] {
    cursor: pointer;
}

.project-card[role="button"]:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 3px;
}

.project-detail-modal {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(10px);
    z-index: 11000;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.25s ease;
    padding: 1.2rem 1rem;
    overflow-y: auto;
}

.project-detail-modal.active {
    opacity: 1;
    visibility: visible;
}

.project-detail-panel {
    width: min(1100px, 100%);
    margin: 0 auto;
    background: var(--dark-secondary);
    border: 1px solid var(--dark-tertiary);
    border-radius: 16px;
    box-shadow: 0 30px 60px rgba(0, 0, 0, 0.45);
    padding: 1.4rem;
    display: flex;
    flex-direction: column;
    gap: 1.6rem;
    position: relative;
}

.project-detail-panel section {
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 0.8rem;
}

.project-detail-close {
    position: absolute;
    top: 16px;
    right: 16px;
    border: 1px solid var(--dark-tertiary);
    background: var(--dark-bg);
    color: var(--text-primary);
    width: 40px;
    height: 40px;
    border-radius: 50%;
    font-size: 1.4rem;
    line-height: 1;
    cursor: pointer;
}

.project-detail-close:hover {
    border-color: var(--primary-color);
    color: var(--primary-color);
}

.project-detail-header {
    display: flex;
    flex-direction: column;
    gap: 0.7rem;
}

.project-detail-header h3 {
    font-size: 1.7rem;
    margin: 0;
}

.project-detail-header p {
    color: var(--text-secondary);
    font-size: 0.96rem;
    margin: 0;
}

.project-detail-kicker {
    display: inline-block;
    margin: 0;
    color: var(--primary-color);
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-size: 0.8rem;
}

.project-detail-video h4,
.project-detail-description h4,
.project-detail-grid h4,
.project-detail-gallery-wrap h4,
.project-detail-links-wrap h4 {
    margin: 0;
    font-size: 0.98rem;
    letter-spacing: 0.02em;
}

.project-video-wrapper {
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid var(--dark-tertiary);
    background: #000;
    aspect-ratio: 16 / 9;
}

.project-video-wrapper iframe {
    width: 100%;
    height: 100%;
    border: 0;
}

.project-detail-description p {
    color: var(--text-secondary);
    line-height: 1.55;
    margin: 0;
}

.project-detail-grid {
    display: grid;
    grid-template-columns: 1fr 1.25fr;
    gap: 0.8rem;
}

.project-detail-list {
    list-style: none;
    padding: 0;
    margin: 0.04rem 0 0;
}

.project-detail-list li {
    position: relative;
    padding-left: 1.2rem;
    margin-bottom: 0.18rem;
    color: var(--text-secondary);
}

.project-detail-list li:last-child {
    margin-bottom: 0;
}

.project-detail-list li::before {
    content: '•';
    color: var(--primary-color);
    position: absolute;
    left: 0;
}

.project-detail-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35rem;
}

.project-detail-grid h4 + .project-detail-tags {
    margin-top: 0.55rem;
}

.project-detail-chip {
    background: var(--dark-bg);
    border: 1px solid var(--dark-tertiary);
    color: var(--text-primary);
    padding: 0.45rem 0.8rem;
    border-radius: 999px;
    font-size: 0.88rem;
}

.project-detail-gallery {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 0.1rem;
}

.project-gallery-item {
    margin: 2px;
    padding: 0;
    border-radius: 10px;
    overflow: hidden;
    border: 1px solid var(--dark-tertiary);
    background: var(--dark-bg);
    min-height: 100px;
    aspect-ratio: 16 / 9;
    cursor: pointer;
    transition: transform 0.2s ease, border-color 0.2s ease;
}

.project-gallery-item:hover {
    transform: translateY(-2px);
    border-color: var(--primary-color);
}

.project-gallery-item:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}

.project-gallery-item img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    max-width: 100%;
}

.project-detail-links {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.project-detail-link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    text-decoration: none;
    width: 44px;
    height: 44px;
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.95), rgba(236, 72, 153, 0.95));
    border: 1px solid rgba(248, 250, 252, 0.28);
    color: #fff;
    padding: 0;
    border-radius: 12px;
    box-shadow: 0 6px 16px rgba(99, 102, 241, 0.3);
    transition: all 0.2s ease;
}

.project-detail-link:hover {
    color: #fff;
    border-color: rgba(248, 250, 252, 0.6);
    transform: translateY(-2px) scale(1.05);
    box-shadow: 0 10px 22px rgba(236, 72, 153, 0.35);
}

.project-detail-link svg {
    width: 20px;
    height: 20px;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.project-lightbox {
    position: fixed;
    inset: 0;
    background: rgba(2, 6, 23, 0.9);
    backdrop-filter: blur(10px);
    z-index: 12000;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.2s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}

.project-lightbox.active {
    opacity: 1;
    visibility: visible;
}

.project-lightbox-image {
    max-width: min(1400px, 96vw);
    max-height: 88vh;
    border-radius: 14px;
    border: 1px solid rgba(148, 163, 184, 0.35);
    box-shadow: 0 18px 60px rgba(0, 0, 0, 0.55);
}

.project-lightbox-close {
    position: fixed;
    top: 16px;
    right: 20px;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    border: 1px solid rgba(248, 250, 252, 0.4);
    background: linear-gradient(135deg, rgba(99, 102, 241, 0.95), rgba(236, 72, 153, 0.95));
    color: #fff;
    font-size: 1.5rem;
    line-height: 1;
    cursor: pointer;
}

@media (max-width: 900px) {
    .project-detail-panel {
        padding: 1rem;
    }

    .project-detail-header h3 {
        font-size: 1.5rem;
        padding-right: 2.2rem;
    }

    .project-detail-grid {
        grid-template-columns: 1fr;
    }
}
